function sponge(text){
  var out=''; var up=false;
  for(var i=0;i<text.length;i++){ var c=text[i];
    if(/[a-zA-Z]/.test(c)){ up=!up; out+= up? c.toUpperCase():c.toLowerCase(); }
    else out+=c;
  }
  return out;
}
var EXPORTS={sponge:sponge};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpongeForgePure = EXPORTS; }
